// ── Pathways: the ordered stages each cohort should move through ─

export const PATHWAYS: Pathway[] = [
  { cohort: "economic-shock", steps: ["prevention", "diversion", "emergency-shelter", "rapid-rehousing", "retention"], evidence: "RCT", evidenceSource: "santa-clara-rct", why: "Cash inside the 10-day notice clock beats shelter: Santa Clara's randomized trial cut homelessness 81% at six months on an average $4,442; Chicago emergency assistance cut shelter entry 76%. Shelter is a short motel bridge only if diversion fails; the clinical stages are skipped on purpose." },
  { cohort: "vehicle-homeless", steps: ["prevention", "unsheltered-active", "intake-match", "bridge-transition", "rapid-rehousing", "retention"], evidence: "observational", evidenceSource: "safe-parking-sd", why: "A working household in a vehicle is self-sheltered until the vehicle is towed. Safe parking with sanitation is the bridge; San Diego's program produced housing exits at about four times the rate of bridge shelter. Locally no safe parking with sanitation exists; the former RV site is pods with RVs phased out, so the bridge for this cohort has no local instance." },
  { cohort: "families", steps: ["prevention", "diversion", "emergency-shelter", "rapid-rehousing", "retention"], evidence: "RCT", evidenceSource: "family-options", why: "Same-day non-congregate placement keeps children in school; the Family Options trial found a permanent subsidy halved homelessness and cut shelter stays 75% at 37 months while rapid rehousing showed no stability gain. So the rapid-rehousing stage must convert to a permanent voucher, and retention is where that is verified." },
  { cohort: "youth", steps: ["diversion", "emergency-shelter", "bridge-transition", "rapid-rehousing", "retention"], evidence: "RCT, housing step only", evidenceSource: "chez-soi-youth", why: "Diversion is a safety-screened family-reconnection conversation; shelter must be youth-only within 24–72 hours, never the adult queue; transitional living is the bridge; then a subsidy with support. Only the housing step is trial-backed: an immediate scattered-site lease with case management raised stable-housing days from 31% to 65% for 18–24-year-olds with mental illness in the At Home/Chez Soi subgroup, under the adult model. Youth-only shelter, transitional living, and host homes are practice judgments." },
  { cohort: "dv-trafficking", steps: ["prevention", "emergency-shelter", "rapid-rehousing", "retention"], evidence: "quasi-experimental", evidenceSource: "dvhf-2022", why: "Survivor choice and safety first: flexible cash can prevent the episode; when it cannot, a confidential non-congregate placement the same day, then flexible-funding rapid rehousing with a mobile advocate. Washington's evaluation found better stability, safety, and mental health holding at two years. Survivor records stay in the confidential database and reach the count as flags only." },
  { cohort: "sud", steps: ["unsheltered-active", "crisis-sobering", "withdrawal-management", "bridge-transition", "permanent-supportive-housing", "retention"], evidence: "RCT", evidenceSource: "cm-meta", why: "Survival and engagement in that order. The default is outpatient buprenorphine or methadone with retention, which lowers death, started at whichever door can prescribe, plus a lease not conditioned on abstinence; contingency management for stimulants. Sobering, withdrawal management, and residential treatment are detours taken when indicated and chosen, each with the next bed held, because detox or residential without medication raises overdose death from lost tolerance. Recovery housing by choice, in beds that accept medication. Stabilization is the first placement, not the ticket, and the continuum still lacks an outpatient treatment stage to count this on." },
  { cohort: "smi", steps: ["unsheltered-active", "crisis-sobering", "permanent-supportive-housing", "retention"], evidence: "RCT", evidenceSource: "aubry-2016", why: "The shortest evidence-backed path is from the street to a lease with an ACT team, with crisis stabilization as a detour when needed and inpatient care in parallel, not as a prerequisite: 71% of time stably housed versus 29% over 24 months in the high-needs arm, an advantage that narrowed but held to year six in Toronto. If hospitalized, the path re-enters through in-reach with a transition worker assigned before discharge." },
  { cohort: "dual-diagnosis", steps: ["unsheltered-active", "crisis-sobering", "withdrawal-management", "bridge-transition", "permanent-supportive-housing", "retention"], evidence: "RCT", evidenceSource: "pathways-2004", why: "One team, one plan. The Pathways trial enrolled people with serious mental illness, nine in ten with a recorded substance disorder or history: housing without prerequisites produced earlier and more stable tenancies with no difference in self-reported substance use at 24 or 48 months. A days-to-weeks behavioral-health transitional shelter holds the person only while a unit is found; the lease comes with an integrated team offering medication and contingency management. The failure to design out is serial systems that each say get the other thing fixed first." },
  { cohort: "medical-fragile", steps: ["institutional-exit", "medical-respite", "permanent-supportive-housing", "retention"], evidence: "quasi-experimental", evidenceSource: "kertesz-2009", why: "Never a discharge to the street: the housing worker is attached at admission, respite is arranged before discharge, and the exit from respite is a lease or a long-term-care placement with in-home supports. Respite roughly halved 90-day readmission odds; housing plus case management cut hospitalizations 29% in a randomized trial." },
  { cohort: "chronic-stable", steps: ["unsheltered-active", "intake-match", "emergency-shelter", "permanent-supportive-housing", "retention"], evidence: "observational", evidenceSource: "kuhn-culhane", why: "Long-term homeless without an acute crisis: verified with a named lead, assessed and matched within 90 days, held in low-barrier shelter or a village only while documents and the unit come together, then supportive housing. The chronic 10% used half of all shelter days in the typology study; the county prices supportive housing at $16,000 per person against $47,000 per shelter bed." },
  { cohort: "justice-involved", steps: ["institutional-exit", "bridge-transition", "permanent-supportive-housing", "retention"], evidence: "RCT", evidenceSource: "urban-denver", why: "Reach in before release or immediately after, hold a bridge or interim bed, and reach supportive housing within about 90–120 days; the studies tested bridge-then-housing, not jail-door-to-lease. Sobering or detox are detours on release day, never conditions. Just in Reach: 82% housed 12 months after placement; Denver's randomized trial: 27% fewer jail days over three years; NYC FUSE: 40% fewer jail days." },
  { cohort: "service-refusing", steps: ["unsheltered-active", "bridge-transition", "permanent-supportive-housing", "retention"], evidence: "observational", evidenceSource: "abt-encampments", why: "Refusal is usually a refusal of a specific offer. The same small team returns repeatedly, backed by a clinical line to tell refusal from untreated psychosis or withdrawal, and makes a documented non-congregate offer that takes the pet, the partner, and the belongings, then a lease. The count records the decline reason rather than the label." },
];

// ── The shared first-door protocol ────────────────────────────────

export interface FirstDoorStep {
  n: number;
  ask: string;
  /** What any responder can observe to answer it, without a diagnosis. */
  observe: string;
  ifYes: string;
  door: string;
  stageId: string;
  /** Local door today, named. */
  today: string;
}

/**
 * Six questions, in order, that a police officer, paramedic, outreach worker,
 * emergency department, or jail release planner can answer at the scene with
 * what they can see. Each yes names the first door. The order matters:
 * safety, then stabilization, then population, then history.
 */
export const FIRST_DOOR: FirstDoorStep[] = [
  { n: 1, ask: "Is there an immediate danger to life?", observe: "Overdose signs, unresponsive, severe injury or illness, active suicidal or homicidal statements, violence in progress. Also treat as danger to life: hot or soaked with sweat, racing pulse, cannot be redirected even for a minute, or sudden violence, which is a medical emergency that looks like psychosis.", ifYes: "Medical or psychiatric emergency first. This is not yet a homelessness decision; the homelessness decision starts at discharge, with a county in-reach worker (not hospital staff, who have no housing role and no HMIS access) attached at admission. An emergency-department visit that ends without admission is recorded as a contact and routed to a named lead.", door: "EMS, emergency department, or psychiatric emergency", stageId: "institutional-exit", today: "911 and any emergency department for medical, overdose, or injury. Unity Center 24-hour psychiatric emergency for adults 18–70 who are medically clear and voluntary or on a police hold; a paramedic cannot place a hold. Under 18: Unity takes no adolescent walk-ins; the door is 911, an emergency department, or child welfare." },
  { n: 2, ask: "Intoxicated or in withdrawal, without a medical emergency?", observe: "Two different people. (a) Intoxicated but walking, oriented, breathing normally, and able to agree to go. (b) Withdrawal signs (shaking hands, drenching sweat, vomiting, confusion, any seizure history), too impaired to walk or to agree, or a psychiatric component. Alcohol and benzodiazepine withdrawal can kill within days.", ifYes: "Never a cell or a waiting room, which is Oregon law (ORS 430.399), not a preference. (a) Sobering, by a referral partner who transports. (b) Medical withdrawal management or an emergency department tonight; sobering will refuse this person. Naloxone in hand for everyone. Buprenorphine now only at a door that can prescribe (Unity, any emergency department, a bridge clinic, Hooper); if the person is still intoxicated, a timed re-approach within 12–24 hours and a held next-morning induction. Hold the next stage before discharge.", door: "Sobering if able to consent; otherwise medical withdrawal management or an emergency department", stageId: "crisis-sobering", today: "Coordinated Care Pathway Center sobering: 13 stations, 24/7, adults 18 and over who are intoxicated, can knowingly and voluntarily agree, and have no medical or mental-health emergency. Referral-only from twelve named partners (police, Portland Street Response, Portland Fire & Rescue CHAT, Project Respond, and named outreach and peer teams); the referrer transports; no walk-in, no phone referral, no emergency-department or jail-release referral. Unity Center: 24/7 police and emergency-responder drop-off for acute intoxication, nine withdrawal-management beds, adults only. Hooper detox: admission Monday to Friday 6:45–7:45 a.m., state ID and a ten-day medication supply required. Field buprenorphine: Portland Fire & Rescue CHAT, Monday to Thursday 8–5:30 only. When sobering declines someone, ORS 430.399 lets police take them to jail; count that as a failed exit." },
  { n: 3, ask: "Psychiatric crisis below the danger threshold?", observe: "Disorganized speech or behavior, apparent psychosis, acute distress; cannot make a decision today but is not a danger to self or others. If hot, sweating, racing pulse, or non-redirectable, go back to question 1.", ifYes: "Voluntary only: below the danger standard no officer, medic, or crisis worker can hold anyone. Mobile crisis or crisis stabilization with a warm handoff and a transition worker. If the person refuses, document, code the decline against the offer, and task a return within 12–24 hours; a qualified mental health professional who believes commitment criteria are met may request a director's hold (ORS 426.233). Jail is a failure of this step. If the person has a disabling condition and a long history outside, the lease offer is made from here, not after treatment.", door: "Mobile crisis or crisis stabilization", stageId: "crisis-sobering", today: "Midnight to 6 a.m.: county crisis line 503-988-4888 dispatches Project Respond (contract target one hour), or a consensual ride to Unity for adults 18–70 who are oriented and medically clear. 6 a.m. to midnight: Portland Street Response via 911 or 503-823-7773. No 72-hour crisis-stabilization facility exists in the county; Unity's psychiatric emergency service, about 23 hours, is the only observation capacity." },
  { n: 4, ask: "Children present, under 25, or fleeing violence?", observe: "Minor children with the household; a young adult alone; disclosure of intimate-partner or sexual violence or trafficking, or visible fear of a specific person.", ifYes: "The population door, non-congregate, never the adult queue. Same day is the target; tonight it mostly does not exist, so log no door open rather than route to an adult bed. For survivors the responder records a living situation only, no violence flag and no referral row; the advocate logs the referral in the confidential database, and survivor choice governs from the advocate's first contact (police act under the arrest duty in ORS 133.055). Under 16 is child welfare, not the youth shelter system.", door: "Family, youth, or survivor system", stageId: "emergency-shelter", today: "Families: 211 (8 a.m.–7 p.m. weekdays, 2–10 p.m. weekends) takes the name; a specialist calls back within 72 hours; county family shelter is reservation-based; no same-night family placement exists for a responder. Youth 16–24: Porch Light, 1635 SW Alder, self-referral at the door 9 p.m.–5 a.m., first come; Janus Access Center 9–5 for intake. Survivors: Call to Safety 503-235-5333, 24/7 phone advocacy; shelter follows a safety assessment with beds checked at 9 a.m.; overnight is advocacy and a hotel voucher when funds allow." },
  { n: 5, ask: "First time, or recently housed?", observe: "Ask and check, since first-time status is not visible: lost housing within roughly 90 days; still has belongings, documents, income, or a lease history; can name a person or place they could return to with help; no prior contacts in your own records.", ifYes: "Diversion and prevention cash before any bed: a problem-solving conversation, a payment inside days, a landlord call. Rapid rehousing if a unit is needed. Do not enter this person into a queue built for chronic cases, and never let the diversion conversation become a screen-out; federal coordinated-entry rules forbid it.", door: "Diversion with flexible cash, then rapid rehousing", stageId: "diversion", today: "No diversion function exists. SHS eviction prevention and the Medicaid six-month rent benefit are the closest tools, neither available at the point of first contact. Interim: record the HMIS 'resources or support network for other housing' answer on first contact, so the diversion cohort is counted before the stage is funded." },
  { n: 6, ask: "None of the above: long-term outside, or leaving an institution?", observe: "Ask and check: months or years outside; repeated episodes or repeated contacts in your records; a disabling condition apparent or documented; or inside a jail, hospital, or treatment program with a release date.", ifYes: "Verify on the list with a named lead within 7 days, assess within 10, match within 90. Offer a lease with services matched to acuity; use stabilization and bridge stages as first placements, never as conditions. From an institution, arrange the next place before the door opens; for a jail that means the booking interview, since the median stay is about a day and release times are not announced.", door: "Verified list and housing match; institutional in-reach", stageId: "unsheltered-active", today: "Coordinated Housing Access Team warmline 844-765-9384 (county, adults) requests an assessment; it does not produce a bed or a lead, and its hours are unpublished. No county adult shelter has night walk-in intake; city overnight shelters (first come, roughly 8 or 9 p.m. to 6:30 or 8 a.m.) are the only night bed for a single adult. Jail: reach-in for people on or entering supervision (9 staff, about 296 housed a month); no in-reach for pretrial releases, which are most releases; no referral path from the release window. Hospitals: no in-reach; Project Respond's emergency-department liaisons are the only embedded link." },
];

