export interface LadderStep { n: number; title: string; body: string; law?: string }

export const REFUSAL_LADDER: LadderStep[] = [
  { n: 1, title: "First ask who is refusing", body: "A no from someone intoxicated, in withdrawal, or in psychosis is not a decline; it is a deferral. Re-approach within 12–24 hours. If the person is incapacitated in public, the law already says where they go: a treatment or sobering facility, an emergency department, or Unity, and jail only when nothing will admit them. If they are a danger to themselves or others, an officer can take custody. Below those two lines, nobody can make anyone go anywhere, and the protocol says so.", law: "ORS 430.399; ORS 426.228" },
  { n: 2, title: "Then ask what was offered", body: "Most refusals are refusals of a specific offer: a congregate bed across town with no pets, no partner, no storage, a curfew, and a sobriety rule. That is not an offer for the person who said no. Record the reason against the offer (site and rule), not against the person, and fix the offer: non-congregate, takes the pet and the partner and the belongings, near the person's community, with a ride and a held bed." },
  { n: 3, title: "Same small team, back tomorrow", body: "The evidence for encampment resolution is sustained contact by the same few workers who return repeatedly with a real offer, not a one-time visit with a clipboard. The named lead keeps the case; each attempt is documented; the person stays on the verified list in the presumed band, which is the team's re-find list, never a headcount." },
  { n: 4, title: "Bring the clinical line to the sidewalk", body: "A 24/7 consult line tells refusal from untreated psychosis or withdrawal. Where a qualified mental health professional believes the commitment standard is met, they can request a director's hold; since January 2026 that standard reaches foreseeable harm and basic needs, not only imminent danger, and outpatient orders exist. The order is only useful if a bed and a team are waiting at the other end.", law: "ORS 426.233; ORS 426.131 and 426.133 (HB 2005)" },
  { n: 5, title: "Never write 'service-refusing'", body: "The person's row reads contact, no referral. Declines live on the offer, aggregated nightly with no person key, because a dated per-person decline log is prosecution evidence under the city's camping ordinance and a target for data requests. Refusing a service or a data question never lowers the lane or eligibility for any later door; federal coordinated-entry rules require refusal without retribution.", law: "Portland City Code 14A.50.150; HUD Notice CPD-17-01 II.B.11" },
  { n: 6, title: "Enforcement last, and only after a real offer", body: "The camping ordinance requires that the person was offered and rejected reasonable alternate shelter. So the offer must be real (a bed the person could use, that night, with a ride) and documented at the offer level before any citation or removal. Removal follows a sequence: notice, the outreach lead present, belongings stored and retrievable, medications and documents protected, no removal of someone mid-treatment. Modeling of repeated involuntary displacement of people who inject drugs shows more deaths, so enforcement is a public-order tool with a health cost, not a housing intervention, and every post-removal contact is counted." },
  { n: 7, title: "Count the no", body: "Each night's declines by offer and rule, the no-door-open codes by hour, and the re-approach outcomes are published beside the headline count. That is how a refusal stops being a story about the person and becomes a finding about the door." },
];

export const POLICE_ROLE: string[] = [
  "Police are the most common first contact at night and the only responder who can transport under ORS 430.399 or take custody under ORS 426.228. Those two statutes are the whole of their authority here.",
  "They open three doors tonight: sobering (for the intoxicated adult who can agree), Unity (intoxication or psychiatric emergency, adults), and an emergency department. They cannot open a shelter, a family placement, a youth bed, or a housing assessment at 2 a.m., and the protocol does not pretend they can.",
  "Their record is a dispatch disposition (offered X, declined with reason, transported to Y, arrival time), matched monthly to the receiving door's log. They never enter HMIS and never write a warrant into a shared record.",
  "Camping enforcement is a day-unit procedure after a documented, usable offer; it is not the model contact. A warrant hit at the scene means jail, coded as door refused, not as the person's decline.",
  "Police presence at any stage after the first door (assessment, detox, treatment, shelter intake, housing) is a sign the system failed a step, and is counted that way.",
];

export const OFF_THE_STREET: string[] = [
  "Know who is outside, by name, with a named lead and a next step (stage 3). Identified is not engaged; the county's own count of newly engaged people is the number that has to move.",
  "Offer the right first door for the person in front of you (the six questions), not the bed that happens to be open. A first-time family gets cash and a motel, not the chronic queue; a person in withdrawal gets medical care, not sobering; a person in psychosis gets a crisis worker, not a cell.",
  "Make the offer real: non-congregate where it matters, takes the pet and the partner and the belongings, with a held bed, a ride, and an arrival written by the receiving site. Most nights the honest answer is that no such door is open, and the design counts that as the missing door, not as a refusal.",
  "Hold the person's place in the next stage before they leave this one: the bed after detox, the unit after treatment, the worker before the jail door opens. Transitions are where people are lost.",
  "For the highest-acuity few, stabilization first for hours to weeks, then a lease with an ACT team, master leasing, and a risk fund. Roughly a tenth of the people account for half the shelter nights and most of the public-safety contacts; the whole system is judged on whether they stop cycling.",
  "Enforcement only after all of that, on the record, with belongings stored, and with the outreach lead present. It moves people; it does not house them, and the count should show where they went.",
];

// ── What the front line will say ─────────────────────────────────

export interface Objection { role: string; says: string; answer: string }

export const OBJECTIONS: Objection[] = [
  { role: "Outreach workers", says: "You are adding data entry to a job that already has forty fields and a separate mapping tool.", answer: "At the scene nothing new is written. Two fields at end of shift (referral result and arrival status) join the contact row the handbook already requires, and the county retires the parallel mapping-tool count the same day, so this is one entry instead of two." },
  { role: "Outreach workers", says: "A named lead within 7 days is fantasy with six workers for 1,800 verified people.", answer: "The rule comes with a caseload ceiling per worker and a visible lead-capacity-exhausted state. When the ceiling is hit the gap is published as staffing, not as your failure. The county cut its ten navigators to zero; the design makes that cut legible." },
  { role: "Outreach workers", says: "Yes-to-arrival within 24 hours will make us look like we fail every night.", answer: "A yes with no door open at that hour is coded no door open and reported as a capacity finding by door and hour, never as a worker or program score. The metric is red by construction until the sobering and withdrawal center opens, and it is meant to be." },
  { role: "Outreach workers", says: "The city's camp teams and police make most of the offers to my caseload and I cannot see them.", answer: "City Street Services and police offers write the referral event and result into the shared row, or the yes-to-arrival headline is labeled county-contracted outreach only until they do. A cross-program offer view is part of the named-lead design." },
  { role: "Outreach workers", says: "Belongings, storage, and dogs decide more refusals than anything on your list.", answer: "Belongings and storage, pets, partner, and community are decline reasons coded against the offer, and storage capacity becomes a counted resource alongside beds and transport." },
  { role: "Outreach workers", says: "Some camps I cannot safely approach, and a contact with no offer will look like I did nothing.", answer: "A worker-safety code (dog, weapon, unsafe to approach) explains a contact that produced no offer without coding the person. Attempted, not found, and seen, not engaged, are their own states." },
  { role: "Police", says: "We do not have HMIS and never will.", answer: "You are not asked to. The record is a dispatch disposition set (offered, declined with reason, transported to, arrival time), matched monthly to the receiving door's admission log. Entering it into the system of record is the receiving site's job." },
  { role: "Police", says: "Sobering will not take the drunk who cannot stand. What do I do at 2 a.m.?", answer: "ORS 430.399 says an incapacitated person goes to a treatment facility or an emergency department; Unity takes intoxication drop-offs for adults 24/7; jail is lawful only when nothing will admit them, and the count records that as a system failure, not the person's. The protocol names those doors and their hours." },
  { role: "Police", says: "I have no authority to make anyone go anywhere below the danger standard.", answer: "Correct, and the rules say so in plain words: transport is voluntary unless ORS 426.228 or 430.399 applies. Every use of the word hold in the design means a held bed, not a detention." },
  { role: "Police", says: "If there is a warrant, the person is going to jail whatever your protocol says.", answer: "Then the referral result is door refused, charge ineligibility, not the person's decline, and the warrant is never written into the shared record. Fire CHAT does not run warrants, so a CHAT referral to sobering is not blocked by one." },
  { role: "Police", says: "Transport ties up a car for an hour and I have calls holding.", answer: "The rule names who transports per door: the referring team for sobering, police or EMS for Unity, an ambulance for an emergency department, a dispatched ride for shelter with the arrival still confirmed by the site. Where no transport exists at that hour the result is coded no transport, so the missing piece is named." },
  { role: "Police", says: "The camping ordinance requires an offer and a refusal. Is this list our evidence?", answer: "No. Declines are recorded against the offer, aggregated, with no person key, and the design carries a written non-disclosure rule for enforcement requests. Enforcement documentation is the city's separate record of a specific, usable offer." },
  { role: "Paramedics and fire", says: "Half of the people your intoxication question describes fail the deflection-center transport criteria.", answer: "The question is now two branches with the vital-sign and orientation gate in the observable text: walking, oriented, able to agree goes to sobering; withdrawal signs, unable to walk or agree, or a psychiatric component goes to medical care." },
  { role: "Paramedics and fire", says: "We cannot start buprenorphine on someone who is high, and CHAT's induction program runs weekdays until 5:30.", answer: "Induction happens at a prescribing door in withdrawal (Unity, an emergency department, a bridge clinic, Hooper). For someone still intoxicated the protocol says naloxone in hand, a timed re-approach, and a held next-morning induction slot." },
  { role: "Paramedics and fire", says: "Fire apparatus cannot transport to a shelter outside a declared emergency.", answer: "The rule names the authorized transporter per destination and allows a dispatched ride with the arrival confirmed by the site. Fire is never asked to transport where its protocol forbids it." },
  { role: "Paramedics and fire", says: "Refusal with capacity is a documented legal disposition and your questions have no branch for it.", answer: "Each stabilization question now has a refusal path: document capacity, code the decline against the offer, task a re-contact within 12–24 hours, and push the result to the outreach lead." },
  { role: "The jail", says: "The median stay is about a day. A 72-hour in-reach flag fires after most people are already on the sidewalk.", answer: "The living-situation question moves to the booking interview, which recognizance staff already run for every booking around the clock. Stays under 72 hours get a release-day handoff standard; longer stays get a worker." },
  { role: "The jail", says: "The Sheriff does not decide who leaves or when. Do not attribute street releases to us.", answer: "Discharge-to-street events are attributed by release authority (recognizance, court order or dismissal, bail, time served, emergency release, transfer), and the destination gap is owned at the system level by the body that spans Sheriff, courts, DA, and DCJ." },
  { role: "The jail", says: "Release processing takes hours and release times are not given out. A held bed with a 5 p.m. cutoff is useless.", answer: "The hold becomes a release window, not a time, and the release notification to the receiving site becomes a counted event; the jail already runs victim notification on the same trigger." },
  { role: "The jail", says: "There is no housing field in the booking system, and two of the three record systems are not the county's.", answer: "The field is added to the booking record as living situation, so it is not confused with cell classification, collected at the recognizance interview. The design names the Sheriff and the circuit court as the owners the county board does not control." },
  { role: "Hospitals", says: "We have social workers, not housing workers, and no HMIS access.", answer: "The in-reach worker is a county worker inside the hospital or the coordinated-care network under a business associate agreement, or is named in an authorization signed at the admission housing question. Hospital staff are not asked to run assessments." },
  { role: "Hospitals", says: "Most of our homeless encounters are treat-and-release emergency visits that end at 3 a.m., never admissions.", answer: "An emergency visit without admission is recorded as a contact with a living situation and a referral result and routed to a named lead, the same as an outreach contact. The 72-hour clock applies to admissions only." },
  { role: "Hospitals", says: "Discharge code 01 is the routine code every housed patient gets. It does not mean street.", answer: "The design drops the disposition code and builds discharge-to-street from a destination log: named site, bed confirmed, transport provided, time. The federal housing screen you already run at admission is the flag, extended to emergency discharges." },
  { role: "Hospitals", says: "Respite refuses anyone who cannot walk or manage medication, and it takes referrals weekdays 8 to 5. Where does the rest go?", answer: "The respite entry splits into respite-eligible and needs skilled or long-term care, the second on a named clock (eligibility screen, the extended skilled-nursing benefit, guardianship). Referrals declined for criteria are counted separately from those declined for capacity." },
  { role: "Hospitals", says: "The patient who said yes to detox at 2 a.m. sits in our lobby until Hooper opens at 6:45. Is that a failed arrival?", answer: "No. Held in place, with the door and its opening hour named, is a counted interim state; the clock runs until arrival. The one-hour weekday window is published as the door's rule." },
  { role: "Clinicians", says: "Alcohol and benzodiazepine withdrawal kill in days. Never route that to a sobering station.", answer: "Withdrawal signs (shaking, drenching sweat, vomiting, confusion, seizure history) route to medical withdrawal management or an emergency department in the protocol's second branch, and alcohol is named as a gap the count does not yet separate." },
  { role: "Clinicians", says: "Methamphetamine psychosis can take weeks to clear, not hours or days.", answer: "The rule now says hours to days for intoxication and most withdrawal, days to weeks for stimulant or primary psychosis, with the housing offer made from the stabilization bed as soon as the person can say yes to a room and the lease held by the system where signing capacity is in doubt." },
  { role: "Clinicians", says: "Detox followed by residential treatment without medication raises overdose death from lost tolerance.", answer: "Outpatient medication with retention is the default for opioid use; detox and residential are detours taken when indicated and chosen, each with the next bed held; deaths within 30 days of leaving any institution become a counted number. The continuum still lacks an outpatient treatment stage, and the caveats say so." },
  { role: "Clinicians", says: "Oxford Houses vote, and they vote out people on buprenorphine.", answer: "The recovery-housing registry records per house whether it accepts residents on medication, and only those beds count as capacity for the substance-use cohorts. Acceptance becomes a condition of county-funded beds." },
  { role: "Clinicians", says: "Cannot consent is a capacity determination. An officer or outreach worker cannot make it.", answer: "It is no longer a lane criterion. Impaired tonight is a deferral, re-approached within 12–24 hours; Lane 3 is scored on repeated contacts. The capacity to accept a room is lower than the capacity to sign a lease, which master leasing sidesteps." },
  { role: "Shelter operators", says: "You are grading us on a destination field our guests will not answer at 6 a.m.", answer: "An unknown share above 10% flags the site on data before outcomes, and the design funds a check-out conversation as part of the bed-night. The honest finding stands: the worst-reporting sites are the likeliest to be recycling people to the street." },
  { role: "Shelter operators", says: "Arrival confirmation and referral source are another form.", answer: "They are two fields on the bed-night bill you already submit, not a new form, and they are the only way a 2 a.m. yes becomes visible instead of argued about." },
  { role: "Shelter operators", says: "Our decline rules (no pets, sobriety, curfew) are why our building is safe.", answer: "Keep them, and publish them as the door's rules so the count can show which lock fails for whom. The fix is funding non-congregate alternatives for the people those rules exclude, not forcing every site to take everyone." },
  { role: "Housing providers and landlords", says: "High-acuity tenants wreck units and drive out other tenants.", answer: "Lane 3 comes with master leasing where the system holds the lease, a damage and vacancy fund, a rapid tenancy-response team, and capped volume; a police call triggers the team, not eviction." },
  { role: "Housing providers and landlords", says: "A fidelity score punishes our project-based buildings for not being scattered-site.", answer: "Fidelity is scored on staffing ratios and tenancy terms, where the outcome evidence is, not on the scattered-site item; the one randomized test of concentration found a staffed congregate building housed people as well as scattered-site." },
  { role: "Survivor advocates", says: "Any domestic-violence row in a shared system endangers survivors.", answer: "The first responder records a living situation only, no violence flag, no referral row. The advocate logs the referral in the comparable database and the count receives aggregate flags. Police responders act under their arrest duty; survivor choice governs from the advocate's first contact." },
  { role: "County data staff", says: "The coordinated-entry referral element is not available to outreach projects, and the arrival field does not exist.", answer: "Both are local fields on the outreach contact row until the data standard catches up; the design names which HMIS elements are used where and which are additions." },
  { role: "County data staff", says: "We are mid-migration to a new database and the city's data live somewhere else.", answer: "The first years are a migration and a bilateral negotiation; every published trend is a series break and is labeled as one, with old and new series side by side for at least a year." },
  { role: "People with lived experience", says: "A list that chases 90% coverage and tracks who refused is surveillance.", answer: "Recording requires consent; a refusal to be recorded becomes an anonymous tally, never a person key. No warrant or immigration-relevant code enters the shared record, a written non-disclosure rule covers enforcement requests, and refusing a service or a question never lowers the lane or eligibility." },
  { role: "People with lived experience", says: "Being presumed on a list is not being helped.", answer: "The presumed band exists to send someone back to find you; it is the outreach team's re-find list, not a headcount, and the named-lead rule is what turns identified into engaged." },
];

