// ── Who answers for each stage, and what it costs ────────────────

export interface Accountability {
  stageId: string;
  /** Who answers for the stage: the operating owner and the body that funds or governs it. */
  owner: string;
  /** The mechanism that holds them to it. */
  mechanism: string;
  /** The number they are judged on, with its target. */
  measure: string;
  /** What happens when they miss. */
  ifFails: string;
}

