// ── When Housing First works, and when it does not ────────────────

export interface HfRule {
  verdict: "works" | "works-with-conditions" | "not-by-itself";
  who: string;
  finding: string;
  evidence: string;
  source: string;
}

export const HOUSING_FIRST: HfRule[] = [
  { verdict: "works", who: "Serious mental illness with long or repeated homelessness", finding: "Offer the lease now, with an ACT team for high need and intensive case management for moderate need. Housing First housed people in 73 days against 220 for usual care; neither arm improved quality of life beyond year two, and the ACT result needs ACT teams at fidelity, whose local capacity is unpublished.", evidence: "At Home/Chez Soi high-needs RCT with ACT (n=950, five cities): 71% vs 29% of time stably housed over 24 months. Moderate-needs arm with intensive case management (n=1,198): 73% vs 32%. Toronto-only extension: the advantage held but narrowed by year six (85.5% vs 60.3% for high needs). ACT vs standard case management, meta-analysis of six RCTs: 37% greater reduction in homelessness, no difference in hospitalization.", source: "aubry-2016" },
  { verdict: "works", who: "Co-occurring mental illness and substance use", finding: "Housing without prerequisites and one integrated team. Serial systems that each demand the other problem be fixed first leave the person outside. Medication for opioid use and contingency management are added on their own evidence, not this trial's.", evidence: "Pathways RCT (New York, n=225; serious mental illness required, nine in ten with a recorded substance disorder or history): earlier and more stable housing (about 80% retention vs about 30%) with no difference in self-reported alcohol or drug use at 24 months, and none at 48 months in the same cohort; the treatment-first arm had reason to under-report use.", source: "pathways-2006" },
  { verdict: "works", who: "Frequent jail users", finding: "Reach in before release or immediately after, hold a bridge or interim bed, and reach supportive housing within about 90–120 days. The studies tested bridge-then-housing, not jail-door-to-lease. Supervision conditions that void the tenancy undo it.", evidence: "Just in Reach (Los Angeles, matched, n=336): 82% still housed 12 months after placement, 24 fewer jail days in year one. Denver social impact bond (RCT, n=724): 27% fewer jail days and 40% fewer arrests over three years, intent to treat; 81% of those housed retained at two years. NYC FUSE II (matched): 40% fewer jail days and about 91% fewer shelter days, measured from placement.", source: "urban-denver" },
  { verdict: "works", who: "Young adults 18–24 with mental illness", finding: "An immediate scattered-site lease with intensive case management or ACT by need. Youth-specific service tailoring and youth-only shelter routing are practice judgments, not trial findings.", evidence: "At Home/Chez Soi post-hoc youth subgroup (n=156 of 2,148, ages 18–24 with mental illness): 65% vs 31% of days stably housed over 24 months under the adult model; youth adaptations untested.", source: "chez-soi-youth" },
  { verdict: "works-with-conditions", who: "Families with children", finding: "Housing works, but the intervention is a permanent subsidy, not services and not a time-limited subsidy.", evidence: "Family Options RCT: a subsidy halved homelessness or doubling-up and cut shelter stays 75% at 37 months; rapid rehousing showed no stability gain at 37 months.", source: "family-options" },
  { verdict: "works-with-conditions", who: "Any program calling itself Housing First", finding: "Only at fidelity: standard lease, rent at or below 30% of income, services separate from tenancy, no readiness test, harm reduction, participant-to-staff ratios of ten or fewer. Under-staffed buildings fail; concentration by itself did not in the one trial that tested it, so Portland's project-based stock should be scored on staffing and tenancy terms, not on the scattered-site item.", evidence: "Pathways fidelity scale items 4, 7, 16, 33 (2012 instrument). Fidelity predicts outcomes observationally (86 California programs: homeless days cut 87 at high-fidelity vs 34 at low-fidelity). The Vancouver At Home RCT found congregate Housing First housed people as well as scattered-site (74.3% vs 74.5% of time, against 26.3% for usual care).", source: "somers-2017" },
  { verdict: "works-with-conditions", who: "The highest-acuity few in a scarce market", finding: "Landlords will not take them without system-level risk management: master leasing where the system holds the lease, a damage and vacancy fund, and a rapid tenancy-response team. Per-person cost is higher; volume is capped.", evidence: "A proposal's assumptions, not a trial: the 2026 turnaround plan prices Lane 3 at $45,000–65,000 per person for 900–1,200 people, offset by fewer emergency, jail, and shelter cycles. Master leasing and risk funds are practice in Houston and Hennepin.", source: "meieran-acuity" },
  { verdict: "not-by-itself", who: "As a treatment for substance use", finding: "Housing First keeps people housed and out of emergency rooms. It does not change substance use in either direction. Pair it with medication and contingency management, and judge it on housing and harm, not abstinence.", evidence: "Housing First meta-analysis: stability and reduced emergency use improve; substance use unchanged. Padgett 48-month follow-up: no difference in use.", source: "baxter-meta" },
  { verdict: "not-by-itself", who: "Someone who cannot plan tonight", finding: "In acute intoxication, withdrawal, or psychosis, stabilization comes first: hours to days for intoxication and most withdrawal, days to weeks for stimulant or primary psychosis. The housing offer is made and a unit held from the stabilization bed as soon as the person can say yes to a room; where lease-signing capacity is in doubt the system holds the lease. No trial screened for consent capacity, so this is a sequence, never a readiness test.", evidence: "The stabilize-first lane from the 2026 turnaround proposal, with the Pathways guardrail (fidelity item 7: no housing-readiness requirement); methamphetamine-psychosis course data (about a third of inpatients take over a month to clear).", source: "meieran-acuity" },
  { verdict: "not-by-itself", who: "Someone too sick for a shelter", finding: "A lease cannot deliver wound care. Medical respite first, arranged before hospital discharge, with the housing worker attached at admission.", evidence: "Respite discharge halved 90-day readmission odds; housing plus case management cut hospitalizations 29% in a randomized trial.", source: "kertesz-2009" },
  { verdict: "not-by-itself", who: "Time-limited rapid rehousing as a Housing First substitute", finding: "The subsidy ends before income recovers and the person returns. Track month 25 or the failure is invisible.", evidence: "VA target-trial emulation: instability effect −12.9 points at day 120, −2.4 at three years.", source: "ssvf-2025" },
  { verdict: "not-by-itself", who: "Compulsory treatment as the route in", finding: "Forcing treatment does not produce housing or recovery. Since January 1, 2026 Oregon's commitment standard reaches foreseeable harm and basic needs, not only imminent danger, and outpatient orders exist; the wider door makes the point sharper. An order without a bed and a team produces a discharge, not a recovery.", evidence: "Werb systematic review: no benefit, potential harm in 78% of studies. Massachusetts: opioid overdose death about 2.2 times more likely after involuntary commitment than after voluntary treatment. NC RCT: outpatient commitment helped only with sustained intensive services. HB 2005 (2025), ORS 426.131 and 426.133.", source: "commitment-review" },
  { verdict: "not-by-itself", who: "A region with no units", finding: "Housing First is a placement rule, not a plan. Where the queue over 90 days grows and vouchers sit unleased, the constraint is supply and landlords, and the count should say so rather than blame the model.", evidence: "Coordinated Access assessed 4,853 and placed 484 in FY2024; 1,088 of 1,371 tri-system users were outside supportive housing in the last match.", source: "fuse-multco" },
];

